// The webhook is already authenticated (Header Auth credential); here we only
// make sure the payload is a real batch id before touching the database.
const batchId = String($json.body?.batch_id ?? $json.batch_id ?? '').trim().toLowerCase();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(batchId)) {
  throw new Error(`Invalid or missing batch_id in webhook payload: ${JSON.stringify($json.body ?? {})}`);
}
return { json: { batch_id: batchId, started_at: new Date().toISOString() } };

// STAGE 2 - deterministic scoring, top-K pruning and borderline detection (pure JS, O(pairs)).
//
// 1. Score every Stage-1 pair 0-100 from credit headroom, income headroom,
//    the product's best rate and an affordability check (FOIR).
// 2. Keep only each user's top-K products: nobody needs an email with 14 loans,
//    and every pair we drop here is a pair the LLM never has to look at.
// 3. Split survivors into CLEAR (comfortably eligible -> accepted, no LLM) and
//    BORDERLINE (within a hair of a threshold -> qualitative LLM review).
// 4. Collapse borderline pairs into coarse PROFILE BUCKETS
//    (product x employment x ONLY the dimensions that are actually borderline:
//    a credit-borderline user is bucketed by credit band, and their income is
//    just "comfortably above minimum"). Users in the same bucket get the same
//    answer, so the LLM is asked once per bucket, not once per user - and that
//    answer is cached across batches.

const s1 = $input.first().json;
const MAX_PER_USER = Number($env.MAX_MATCHES_PER_USER || 5);
const FOIR = 0.5;          // max share of income that may go to EMIs (RBI-style fixed-obligation ratio)
const TENURE_MONTHS = 60;
const MIN_USEFUL_LOAN = 50000; // if the user can't service even this, the match is pointless

const products = new Map(s1.products.map(p => [p.product_id, p]));
const clamp01 = x => Math.max(0, Math.min(1, x));
const band = (v, w) => Math.floor(v / w) * w;
const emiPerRupee = (ratePct, n) => { const r = ratePct / 1200; return r ? r / (1 - Math.pow(1 + r, -n)) : 1 / n; };

const byUser = new Map();
let droppedUnaffordable = 0;

for (const [userId, productId, incomeRaw, credit, age, emp] of s1.pairs) {
  const p = products.get(productId);
  const income = Number(incomeRaw);
  const minIncome = Number(p.min_monthly_income || 0);
  const minCredit = Number(p.min_credit_score || 300);
  const rate = Number(p.interest_rate_max ?? p.interest_rate_min ?? 16); // be conservative: assume worst rate

  const affordableLoan = (income * FOIR) / emiPerRupee(rate, TENURE_MONTHS);
  if (affordableLoan < MIN_USEFUL_LOAN) { droppedUnaffordable++; continue; }

  const creditHeadroom = Number(credit) - minCredit;
  const incomeHeadroom = minIncome ? income / minIncome - 1 : 1;
  const ageEdge = age - (p.min_age ?? 18) <= 1 ? 'min' : (p.max_age ?? 100) - age <= 1 ? 'max' : 'mid';

  let score = 100 * (0.40 * clamp01(creditHeadroom / 100)
                   + 0.30 * clamp01(incomeHeadroom)
                   + 0.30 * clamp01((24 - Number(p.interest_rate_min ?? 16)) / 16));
  if (p.criteria_source === 'default') score *= 0.85; // lender didn't publish criteria: less confident

  const reasons = [];
  if (creditHeadroom < 20) reasons.push(`credit score ${credit} is within 20 of the ${minCredit} minimum`);
  if (minIncome && incomeHeadroom < 0.10) reasons.push(`income ${income} is within 10% of the ${minIncome} minimum`);
  if (ageEdge !== 'mid') reasons.push(`age ${age} is at the ${ageEdge} edge of ${p.min_age}-${p.max_age}`);

  const list = byUser.get(userId) || [];
  list.push({ userId, productId, score: Math.round(score * 100) / 100, reasons, income, credit, age, emp, ageEdge,
              maxLoan: Math.round(Math.min(affordableLoan, Number(p.max_loan_amount) || Infinity)) });
  byUser.set(userId, list);
}

const clear = [];       // [userId, productId, score, maxLoan]
const borderline = [];  // [userId, productId, score, maxLoan, bucketKey]
const questions = {};   // bucketKey -> what the LLM needs to judge it
let afterTopK = 0;

for (const list of byUser.values()) {
  list.sort((a, b) => b.score - a.score);
  for (const m of list.slice(0, MAX_PER_USER)) {
    afterTopK++;
    if (!m.reasons.length) { clear.push([m.userId, m.productId, m.score, m.maxLoan]); continue; }
    const incBand = band(m.income, 5000), csBand = band(m.credit, 10);
    const flagged = { income: m.reasons.some(r => r.startsWith('income')),
                      credit: m.reasons.some(r => r.startsWith('credit')), age: m.ageEdge !== 'mid' };
    const profile = {
      monthly_income: flagged.income ? `${incBand}-${incBand + 4999}` : 'comfortably above minimum',
      credit_score: flagged.credit ? `${csBand}-${csBand + 9}` : 'comfortably above minimum',
      employment: m.emp,
      age: flagged.age ? m.age : 'within range',
    };
    const key = `v2|p${m.productId}|${m.emp}|inc:${flagged.income ? incBand : 'ok'}|cs:${flagged.credit ? csBand : 'ok'}|age:${flagged.age ? m.age : 'ok'}`;
    borderline.push([m.userId, m.productId, m.score, m.maxLoan, key]);
    if (!questions[key]) questions[key] = { product_id: m.productId, profile, flags: m.reasons.map(r => r.replace(/\d+ is/, 'is')) };
  }
}

const stats = {
  users_in_batch: s1.users_in_batch,
  products_active: s1.products_active,
  naive_pairs: s1.users_in_batch * s1.products_active,
  stage1_sql_pairs: s1.stage1_pairs,
  stage2_dropped_unaffordable: droppedUnaffordable,
  stage2_after_top_k: afterTopK,
  stage2_clear: clear.length,
  stage2_borderline: borderline.length,
  stage3_unique_questions: Object.keys(questions).length,
};

return [{ json: { batch_id: s1.batch_id, products: s1.products, clear, borderline, questions,
                  question_keys_json: JSON.stringify(Object.keys(questions)), stats } }];

// STAGE 3b - batch the cache misses into a few LLM calls.
// 25 questions per request and a hard per-run call budget keep latency and
// cost bounded no matter how large the upload is. Questions over budget are
// not dropped: they fall back to the rules verdict and get asked next run.
const s2 = $('Stage 2 · Score, top-K, bucket').first().json;
const cached = new Set($input.all().map(i => i.json.cache_key).filter(Boolean));
const misses = Object.keys(s2.questions).filter(k => !cached.has(k));

const PER_CALL = 25;
const MAX_CALLS = Number($env.LLM_MAX_CALLS_PER_RUN || 20);
if (!$env.LLM_API_KEY || !misses.length) {
  return [{ json: { skip: true, misses: misses.length, cache_hits: cached.size, reason: $env.LLM_API_KEY ? 'no cache misses' : 'LLM disabled' } }];
}

const products = new Map(s2.products.map(p => [p.product_id, p]));
const describe = p => ({
  product_id: p.product_id, lender: p.lender, product: p.product_name,
  min_monthly_income: p.min_monthly_income, min_credit_score: p.min_credit_score,
  age: `${p.min_age}-${p.max_age}`, employment_types: p.employment_types ?? 'any',
  other_criteria: p.other_criteria ?? 'none published',
});

const SYSTEM = `You are a conservative credit analyst for Indian unsecured personal loans.
Each case is an applicant PROFILE (ranges, not a single person) that already passes the lender's
hard minimums but sits close to a threshold. Decide if a typical applicant in that profile is
LIKELY to be approved, considering the lender's qualitative criteria, the borderline flags and
standard Indian lending practice (bureau score cut-offs, FOIR, employment stability).
Answer ONLY with JSON: {"decisions":[{"id":"<case id>","eligible":true|false,"reason":"<= 20 words"}]}`;

const toAsk = misses.slice(0, PER_CALL * MAX_CALLS);
const calls = [];
for (let i = 0; i < toAsk.length; i += PER_CALL) {
  const chunk = toAsk.slice(i, i + PER_CALL);
  const productIds = [...new Set(chunk.map(k => s2.questions[k].product_id))];
  const cases = chunk.map((k, j) => ({ id: `c${j + 1}`, ...s2.questions[k] }));
  calls.push({
    json: {
      keys: chunk,
      llm_request: {
        model: $env.LLM_MODEL || 'gemini-3.5-flash-lite',
        temperature: 0,
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: JSON.stringify({ products: productIds.map(id => describe(products.get(id))), cases }) },
        ],
      },
    },
  });
}
return calls;

// Map the LLM's short case ids ("c1".."c25") back to bucket keys.
// One output item carrying all verdicts, ready for a single bulk cache insert.
const s2 = $('Stage 2 · Score, top-K, bucket').first().json;
const plans = $('Plan LLM batches').all().map(i => i.json);

const rows = [];
let failedCalls = 0;
$input.all().forEach((item, idx) => {
  const keys = plans[idx].keys;
  const text = item.json.choices?.[0]?.message?.content || '';
  let decisions = [];
  try { decisions = JSON.parse(text.match(/\{[\s\S]*\}/)[0]).decisions || []; } catch { failedCalls++; return; }
  for (const d of decisions) {
    const key = keys[Number(String(d.id).replace(/\D/g, '')) - 1];
    if (!key || typeof d.eligible !== 'boolean') continue;
    rows.push({ cache_key: key, product_id: s2.questions[key].product_id, eligible: d.eligible,
                reason: String(d.reason || '').slice(0, 300), model: plans[idx].llm_request.model });
  }
});

return [{ json: { rows_json: JSON.stringify(rows), verdicts: rows.length, llm_calls: plans.length, failed_calls: failedCalls } }];

// Final decision per pair:
//   clear pair                         -> match (decision_source = rules)
//   borderline + LLM said eligible     -> match (llm / llm_cache) with the LLM's reason
//   borderline + LLM said NOT eligible -> rejected
//   borderline + no verdict available  -> match (rules_fallback) - hard criteria already passed
// Runs exactly once whichever IF branch was taken (LLM or skip).
const s2 = $('Stage 2 · Score, top-K, bucket').first().json;

const verdicts = new Map();
for (const i of $('LLM cache lookup').all()) {
  if (i.json.cache_key) verdicts.set(i.json.cache_key, { ...i.json, source: 'llm_cache' });
}
let llmMeta = { llm_calls: 0, failed_calls: 0 };
try {
  const parsed = $('Parse LLM verdicts').first().json;
  for (const r of JSON.parse(parsed.rows_json)) verdicts.set(r.cache_key, { ...r, source: 'llm' });
  llmMeta = { llm_calls: parsed.llm_calls, failed_calls: parsed.failed_calls };
} catch (e) { /* LLM branch skipped */ }

const matches = s2.clear.map(([user_id, product_id, score, maxLoan]) => ({
  user_id, product_id, score, decision_source: 'rules',
  reason: `Meets all published criteria; est. affordable loan up to ₹${maxLoan.toLocaleString('en-IN')}`,
}));

let rejected = 0, fallback = 0, cacheHits = 0;
for (const [user_id, product_id, score, maxLoan, key] of s2.borderline) {
  const v = verdicts.get(key);
  if (!v) {
    fallback++;
    matches.push({ user_id, product_id, score, decision_source: 'rules_fallback',
                   reason: 'Borderline on a threshold; passes all hard criteria' });
  } else if (v.eligible) {
    if (v.source === 'llm_cache') cacheHits++;
    matches.push({ user_id, product_id, score, decision_source: v.source, reason: v.reason });
  } else {
    rejected++;
  }
}

const stats = {
  ...s2.stats,
  stage3_cache_hit_buckets: $('LLM cache lookup').all().filter(i => i.json.cache_key).length,
  stage3_llm_calls: llmMeta.llm_calls,
  stage3_llm_failed_calls: llmMeta.failed_calls,
  stage3_llm_rejected_pairs: rejected,
  stage3_rules_fallback_pairs: fallback,
  stage3_pairs_from_cache: cacheHits,
  final_matches: matches.length,
  users_matched: new Set(matches.map(m => m.user_id)).size,
  duration_ms: Date.now() - new Date($('Validate payload').first().json.started_at).getTime(),
};

return [{ json: { batch_id: s2.batch_id, matches_json: JSON.stringify(matches), stats_json: JSON.stringify(stats), stats } }];
